// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {RDF_TYPE} from "../../../main/frontend/graph-explorer/graph-canvas-scope.ts";
import {nodeDetails} from "../../../main/frontend/graph-explorer/node-details.ts";

const nodes = [
  {id: "urn:alice", label: "Alice", kind: "iri"},
  {id: "urn:bob", label: "Bob", kind: "iri"},
  {id: "urn:carol", label: "Carol", kind: "iri"},
  {id: "urn:Person", label: "Person", kind: "iri"},
  {id: '"Alice"@en', label: "Alice", kind: "literal", language: "en"},
  {id: '"Ali"', label: "Ali", kind: "literal"},
  {id: '"39"', label: "39", kind: "literal"},
];
const nodeById = new Map(nodes.map((node) => [node.id, node]));
const edge = (source, predicate, label, target) => ({id: `${source} ${predicate} ${target}`, source, predicate, label, target});
const edges = [
  edge("urn:alice", "urn:name", "name", '"Alice"@en'),
  edge("urn:alice", "urn:knows", "knows", "urn:bob"),
  edge("urn:alice", "urn:age", "age", '"39"'),
  edge("urn:alice", "urn:name", "name", '"Ali"'),
  edge("urn:carol", "urn:knows", "knows", "urn:alice"),
  edge("urn:alice", "urn:knows", "knows", "urn:carol"),
  edge("urn:alice", RDF_TYPE, "type", "urn:Person"),
  edge("urn:bob", "urn:knows", "knows", "urn:carol"),
];

test("values are the node's literal properties, one group per predicate in first-seen order", () => {
  const details = nodeDetails(nodes[0], edges, nodeById);
  assert.deepEqual(details.values.map((group) => [group.label, group.items.map((item) => item.label)]), [
    ["name", ["Alice", "Ali"]],
    ["age", ["39"]],
  ]);
});

test("links group the neighbours per predicate and direction, outgoing first, without rdf:type", () => {
  const details = nodeDetails(nodes[0], edges, nodeById);
  assert.deepEqual(details.links.map((group) => [group.direction, group.label, group.items.map((item) => item.id)]), [
    ["outgoing", "knows", ["urn:bob", "urn:carol"]],
    ["incoming", "knows", ["urn:carol"]],
  ]);
});

test("types come from the hydrated node, or from its rdf:type links while hydration is pending", () => {
  assert.deepEqual(nodeDetails(nodes[0], edges, nodeById).types, [{id: "urn:Person", label: "Person"}]);
  const hydrated = {...nodes[0], types: [{id: "urn:Agent", label: "Agent"}]};
  assert.deepEqual(nodeDetails(hydrated, edges, nodeById).types, [{id: "urn:Agent", label: "Agent"}]);
});

test("neighbours missing from the model are shown by their identifier", () => {
  const details = nodeDetails(nodes[1], [edge("urn:bob", "urn:knows", "knows", "urn:gone")], nodeById);
  assert.deepEqual(details.links[0].items, [{id: "urn:gone", label: "urn:gone", kind: "iri"}]);
});
